const PRIMARY_STORAGE_DIR: &str = ".tazk";

/// Generate long version string with git info and build date
fn long_version() -> &'static str {
    // Allocate version string at runtime, leak it to get 'static lifetime
    // This is called once during CLI initialization
    Box::leak(
        {
            let mut version = env!("CARGO_PKG_VERSION").to_string();

            // Add build date from compile time
            version.push_str(&format!("\nBuilt: {}", env!("BUILD_DATE")));

            // Add git commit if available and working copy is clean
            if let (Some(commit), Some(false)) =
                (built_info::GIT_COMMIT_HASH_SHORT, built_info::GIT_DIRTY)
            {
                version.push_str(&format!("\nCommit: {}", commit));
            }

            version
        }
        .into_boxed_str(),
    )
}

#[derive(Parser)]
#[command(
    name = "tz",
    about = "Tazk - A minimal issue tracker",
    long_version = long_version(),
)]
struct Cli {
    #[command(flatten)]
    global_opts: GlobalOpts,

    #[command(subcommand)]
    command: Commands,
}

#[derive(clap::Args)]
#[command(next_help_heading = "Global Options")]
struct GlobalOpts {
    /// Path to tazk directory
    #[arg(long = "tz-dir", global = true)]
    tz_dir: Option<PathBuf>,

    /// Change working directory before running the command
    #[arg(short = 'C', long = "directory", global = true, hide = true)]
    directory: Option<PathBuf>,

    /// Output JSON format
    #[arg(long, global = true)]
    json: bool,

    /// Reject modifying commands and disable persistent storage writes
    #[arg(long, global = true, hide = true)]
    readonly: bool,

    /// Validation mode for parsing issues: silent, warn, error
    #[arg(
        long = "tz-validation",
        global = true,
        default_value = "error",
        value_name = "MODE"
    )]
    tz_validation: ValidationMode,

    /// Disable command logging to the tazk command_history.log
    #[arg(long = "tz-no-cmd-logging", global = true)]
    tz_no_cmd_logging: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ValidationMode {
    Silent,
    Warn,
    Error,
}

impl std::str::FromStr for ValidationMode {
    type Err = anyhow::Error;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "silent" => Ok(ValidationMode::Silent),
            "warn" => Ok(ValidationMode::Warn),
            "error" => Ok(ValidationMode::Error),
            _ => Err(anyhow::anyhow!(
                "Invalid validation mode: '{}'. Valid values are: silent, warn, error",
                s
            )),
        }
    }
}

#[derive(Subcommand)]
enum Commands {
    /// Initialize tazk in current directory
    Init {
        /// Issue prefix (e.g., 'myproject' for myproject-1, myproject-2)
        #[arg(short, long)]
        prefix: Option<String>,

        /// Use hash-based issue IDs instead of sequential numbers
        #[arg(long = "tz-hash-ids")]
        tz_hash_ids: bool,

        /// Issue file layout for new repos: flat or sharded
        #[arg(long = "tz-issue-layout", default_value = "flat")]
        tz_issue_layout: String,

        /// Suppress init output
        #[arg(short = 'q', long, hide = true)]
        quiet: bool,
    },

    /// Create a new issue
    Create {
        /// Issue title (positional argument, or use --title flag)
        title: Option<String>,

        /// Issue title (alternative to positional argument)
        #[arg(long = "title", allow_hyphen_values = true)]
        title_flag: Option<String>,

        /// Priority (0-4, 0=highest)
        #[arg(short, long, default_value = "2")]
        priority: i32,

        /// Issue type: bug, feature, task, epic, chore
        #[arg(
            short = 't',
            long = "issue-type",
            visible_alias = "type",
            default_value = "task"
        )]
        issue_type: IssueType,

        /// Description
        #[arg(short, long, default_value = "", allow_hyphen_values = true)]
        description: String,

        /// Read the description from a FILE, or from stdin when given `-`.
        ///
        /// Prefer this over `--description` for any multi-line or
        /// markdown-bearing body. Passing prose as an inline shell argument
        /// lets the SHELL expand backticks and `$(...)` before tazk ever
        /// sees the text, which silently stores a mangled description and
        /// still exits 0. Reading from a file or stdin removes the shell from
        /// the path entirely, so there is nothing left to expand.
        #[arg(
            long = "description-file",
            value_name = "PATH",
            conflicts_with = "description"
        )]
        description_file: Option<String>,

        /// Design notes
        #[arg(long, allow_hyphen_values = true)]
        design: Option<String>,

        /// Acceptance criteria
        #[arg(long, allow_hyphen_values = true)]
        acceptance: Option<String>,

        /// Assignee
        #[arg(short = 'a', long)]
        assignee: Option<String>,

        /// Role the issue is for: human, agent (required)
        #[arg(short = 'r', long, required = true)]
        role: Role,

        /// Effort estimate from 1 to 5 (5 is the most effort)
        #[arg(long, value_parser = clap::value_parser!(u8).range(MIN_EFFORT as i64..=MAX_EFFORT as i64))]
        effort: Option<u8>,

        /// Labels (can be specified multiple times)
        #[arg(short, long)]
        label: Vec<String>,

        /// Comma-separated labels
        #[arg(long = "labels")]
        labels: Vec<String>,

        /// External reference
        #[arg(long)]
        external_ref: Option<String>,

        /// Explicit issue ID
        #[arg(long)]
        id: Option<String>,

        /// Dependencies (comma-separated). Formats:
        /// Simple: "tz-1,tz-2" (defaults to 'blocked_by')
        /// Advanced: "blocked_by:tz-1,related_to:tz-2,discovered_from:tz-3"
        #[arg(long)]
        deps: Option<String>,

        /// Parent issue ID for hierarchical child (e.g., 'tz-a3f8e9')
        #[arg(long)]
        parent: Option<String>,

        /// Force creation even if prefix doesn't match database prefix
        #[arg(long)]
        force: bool,

        /// Create multiple issues from markdown file
        #[arg(short = 'f', long)]
        file: Option<PathBuf>,
    },

    /// Triage inbox: plain-text reports kept apart from issues
    ///
    /// A triage item is a plain Markdown file in .tazk/triage/ holding nothing
    /// but text: no title, status, priority, role, assignee, labels,
    /// dependencies or comments. Reporters (code review, validation, testing,
    /// ad hoc feedback) add items without planning them. A triager later
    /// promotes items to issues, attaches them to existing issues as comments,
    /// or removes them. Items are named by creation time, e.g.
    /// 20251104T001800-k3f9.md; commands accept the name with or without .md.
    Triage {
        #[command(subcommand)]
        command: TriageCommands,
    },

    /// List issues
    List {
        /// Filter by status: open, in_progress, closed, blocked, deferred
        #[arg(short = 's', long)]
        status: Option<String>,

        /// Filter by priority (repeatable and/or comma-separated, e.g. "-p 0 -p 1" or "-p 0,1")
        #[arg(short = 'p', long)]
        priority: Vec<String>,

        /// Filter by type: bug, feature, task, epic, chore
        #[arg(long)]
        r#type: Option<IssueType>,

        /// Filter by assignee
        #[arg(long)]
        assignee: Option<String>,

        /// Filter by role: human, agent
        #[arg(short = 'r', long)]
        role: Option<Role>,

        /// Filter by labels (must have ALL specified labels)
        #[arg(short = 'l', long = "label")]
        labels: Vec<String>,

        /// Filter by specific issue IDs (comma-separated)
        #[arg(long)]
        id: Option<String>,

        /// Filter by title substring (case-insensitive)
        #[arg(long)]
        title: Option<String>,

        /// Filter to direct children of a parent issue
        #[arg(long)]
        parent: Option<String>,

        /// Maximum number of issues to return
        #[arg(long)]
        limit: Option<usize>,

        /// Group issues by priority with headers
        #[arg(long)]
        group_priority: bool,
    },

    /// Show issue details
    Show {
        /// Issue IDs (supports shorthand: "14" expands to "prefix-14")
        issue_ids: Vec<String>,
    },

    /// List direct child issues
    Children {
        /// Parent issue ID
        parent_id: String,
    },

    /// Update one or more issues
    Update {
        /// Issue IDs to update
        issue_ids: Vec<String>,

        /// New priority
        #[arg(short, long)]
        priority: Option<i32>,

        /// New assignee
        #[arg(short = 'a', long)]
        assignee: Option<String>,

        /// Clear assignee
        #[arg(long)]
        unassign: bool,

        /// New role: human, agent
        #[arg(short = 'r', long, conflicts_with = "clear_role")]
        role: Option<Role>,

        /// Clear role
        #[arg(long = "clear-role")]
        clear_role: bool,

        /// New effort estimate from 1 to 5 (5 is the most effort)
        #[arg(long, conflicts_with = "clear_effort", value_parser = clap::value_parser!(u8).range(MIN_EFFORT as i64..=MAX_EFFORT as i64))]
        effort: Option<u8>,

        /// Clear effort
        #[arg(long = "clear-effort")]
        clear_effort: bool,

        /// New title
        #[arg(long, allow_hyphen_values = true)]
        title: Option<String>,

        /// New description
        #[arg(short, long, allow_hyphen_values = true)]
        description: Option<String>,

        /// Read the new description from a FILE, or from stdin when given `-`.
        /// See `tz create --help` for why this is preferred over passing prose
        /// as an inline shell argument.
        #[arg(
            long = "description-file",
            value_name = "PATH",
            conflicts_with = "description"
        )]
        description_file: Option<String>,

        /// Targeted edit: find this exact text in a field and swap it for
        /// --replace, instead of overwriting the whole field. Safer for agents
        /// than rewriting a long description wholesale. By default the text must
        /// match exactly once. Requires --replace.
        #[arg(
            long,
            allow_hyphen_values = true,
            requires = "replace",
            conflicts_with_all = ["description", "title", "design", "acceptance", "notes"]
        )]
        search: Option<String>,

        /// Replacement text for --search.
        #[arg(long, allow_hyphen_values = true, requires = "search")]
        replace: Option<String>,

        /// Which field --search/--replace/--append edits: title, description,
        /// design, notes, or acceptance (default: description).
        ///
        #[arg(long = "field", default_value = "description")]
        search_field: EditField,

        /// With --search, replace every occurrence instead of requiring the
        /// search text to match exactly once.
        #[arg(long, requires = "search")]
        replace_all: bool,

        /// Append this text to a field (default description; use --field to pick
        /// another). A blank line is inserted before it when the field already
        /// has content, so the appended text becomes its own paragraph. Saves
        /// having to pass the trailing text as --search/--replace when you just
        /// want to add to the end.
        #[arg(
            long,
            allow_hyphen_values = true,
            conflicts_with_all = ["search", "replace", "replace_all", "description", "title", "design", "acceptance", "notes"]
        )]
        append: Option<String>,

        /// New design notes
        #[arg(long, allow_hyphen_values = true)]
        design: Option<String>,

        /// New acceptance criteria
        #[arg(long, allow_hyphen_values = true)]
        acceptance: Option<String>,

        /// Additional notes
        #[arg(long, allow_hyphen_values = true)]
        notes: Option<String>,

        /// New external reference
        #[arg(long)]
        external_ref: Option<String>,

        /// Add a label. May be provided multiple times.
        #[arg(long = "add-label")]
        add_label: Vec<String>,

        /// Remove a label. May be provided multiple times.
        #[arg(long = "remove-label")]
        remove_label: Vec<String>,

        /// Replace labels with a comma-separated set.
        #[arg(long = "set-labels")]
        set_labels: Option<String>,
    },

    /// Claim or release an issue for cross-machine coordination
    ///
    /// Sets the claim identity (`--as`) as assignee, flips status to
    /// in_progress, and bumps updated_at. An issue that is already in_progress
    /// cannot be claimed unless --force is given. The claim is enforced across
    /// machines by committing and pushing the change: a losing push is
    /// rejected, so the loser pulls and sees the issue is already taken.
    Claim {
        /// Issue IDs to claim (or release with --release)
        issue_ids: Vec<String>,

        /// Claim identity (assignee value), e.g. a worker or agent name
        #[arg(long = "as", required = true)]
        claim_as: String,

        /// Release the claim instead of taking it (returns the issue to the backlog)
        #[arg(long)]
        release: bool,

        /// Team suffix for the claim identity (assignee becomes `<as>/team`)
        #[arg(long)]
        team: Option<String>,

        /// Override the lock: with a claim, take an issue that is already
        /// in_progress; with --release, release a claim held by another worker
        #[arg(long)]
        force: bool,
    },

    /// Close one or more issues
    Close {
        /// Issue IDs to close
        issue_ids: Vec<String>,

        /// Reason for closing
        #[arg(short, long, default_value = "Completed", allow_hyphen_values = true)]
        reason: String,
    },

    /// Reopen closed issues
    Reopen {
        /// Issue IDs to reopen
        issue_ids: Vec<String>,

        /// Reason for reopening
        #[arg(short, long, allow_hyphen_values = true)]
        reason: Option<String>,

        /// Role the issue is for: human, agent. Required when an issue has no
        /// role; replaces the stored role otherwise. (No short form: -r is
        /// already --reason.)
        #[arg(long)]
        role: Option<Role>,
    },

    /// Rename an issue ID
    Rename {
        /// Current issue ID
        old_id: String,

        /// New issue ID
        new_id: String,

        /// Preview changes without applying them
        #[arg(long)]
        dry_run: bool,

        /// Repair broken references (scan all issues and fix stale references)
        #[arg(long)]
        repair: bool,

        /// Also patch code references (requires interactive TTY)
        #[arg(long = "tz-patch-code")]
        tz_patch_code: bool,
    },

    /// Rename the issue prefix for all issues
    RenamePrefix {
        /// New prefix to use
        new_prefix: String,

        /// Preview changes without applying them
        #[arg(long)]
        dry_run: bool,

        /// Force rename even if issues would conflict
        #[arg(long)]
        force: bool,
    },

    /// Manage dependencies
    Dep {
        #[command(subcommand)]
        command: DepCommands,
    },

    /// Manage issue labels
    Label {
        #[command(subcommand)]
        command: LabelCommands,
    },

    /// Manage configuration
    Config {
        #[command(subcommand)]
        command: ConfigCommands,
    },

    /// Manage issue comments
    Comments {
        #[command(subcommand)]
        command: CommentCommands,
    },

    /// Get statistics
    Stats,

    /// Get blocked issues
    Blocked,

    /// Export issues to JSONL format
    Export {
        /// Output file path (defaults to stdout)
        #[arg(short = 'o', long)]
        output: Option<PathBuf>,

        /// Use default file output (storage/issues.jsonl) instead of stdout
        #[arg(long = "tz-output-default")]
        tz_output_default: bool,

        /// Filter by status: open, in_progress, closed, blocked, deferred
        #[arg(long)]
        status: Option<Status>,

        /// Filter by priority
        #[arg(long)]
        priority: Option<i32>,

        /// Filter by type: bug, feature, task, epic, chore
        #[arg(long)]
        r#type: Option<IssueType>,

        /// Filter by assignee
        #[arg(long)]
        assignee: Option<String>,

        /// Filter by role: human, agent
        #[arg(short = 'r', long)]
        role: Option<Role>,
    },

    /// Bidirectional sync between markdown and JSONL formats
    Sync {
        /// Path to JSONL file (defaults to storage/issues.jsonl)
        #[arg(long)]
        jsonl: Option<PathBuf>,

        /// Preview changes without applying them
        #[arg(long)]
        dry_run: bool,

        /// Direction: 'both' (default), 'to-jsonl', or 'to-markdown'
        #[arg(long, default_value = "both")]
        direction: String,
    },

    /// Find ready work (issues with no blockers)
    Ready {
        /// Filter by assignee
        #[arg(short = 'a', long)]
        assignee: Option<String>,

        /// Filter by role: human, agent
        #[arg(short = 'r', long)]
        role: Option<Role>,

        /// Filter by priority (repeatable and/or comma-separated, e.g. "-p 0 -p 1" or "-p 0,1")
        #[arg(short = 'p', long)]
        priority: Vec<String>,

        /// Filter by type: bug, feature, task, epic, chore
        #[arg(long)]
        r#type: Option<IssueType>,

        /// Filter by labels (must have ALL specified labels)
        #[arg(short = 'l', long = "label")]
        labels: Vec<String>,

        /// Filter by specific issue IDs (comma-separated)
        #[arg(long)]
        id: Option<String>,

        /// Filter by title substring (case-insensitive)
        #[arg(long)]
        title: Option<String>,

        /// Filter to direct children of a parent issue
        #[arg(long)]
        parent: Option<String>,

        /// Maximum number of issues to return (default: unlimited)
        #[arg(short = 'n', long)]
        limit: Option<usize>,

        /// Group issues by priority with headers
        #[arg(long)]
        group_priority: bool,

        /// Sort policy: priority (by priority), oldest (by creation date), hybrid (priority + age), random (shuffled)
        #[arg(short = 's', long, default_value = "hybrid")]
        sort: String,
    },

    /// Show quickstart guide
    Quickstart,

    /// Show version information
    #[command(alias = "v")]
    Version,

    /// Git merge driver for issue and comment files
    MergeDriver {
        #[command(subcommand)]
        command: MergeDriverCommands,
    },

    /// Migrate between numeric and hash-based IDs
    Migrate {
        /// Migration direction: 'hash', 'numeric', 'sharded', or 'flat'
        #[arg(long, default_value = "hash")]
        to: String,

        /// Preview changes without applying them
        #[arg(long)]
        dry_run: bool,

        /// Also patch code references (requires interactive TTY)
        #[arg(long = "tz-patch-code")]
        tz_patch_code: bool,

        /// Don't update config-tazk.yaml
        #[arg(long = "no-change-config")]
        no_change_config: bool,

        /// Repack numeric IDs to fill gaps (e.g., 1,3,5 -> 1,2,3)
        #[arg(long = "repack-contiguous")]
        repack_contiguous: bool,

        /// Starting ID for closed issues when repacking (only valid with --repack-contiguous)
        /// Example: --closed-issue-start=1000 packs open issues as 1,2,3... and closed as 1000,1001,1002...
        #[arg(long = "closed-issue-start")]
        closed_issue_start: Option<u32>,
    },
}

impl Commands {
    /// Keep this exhaustive so every new command must declare its write behavior.
    fn is_read_only(&self) -> bool {
        match self {
            Self::List { .. }
            | Self::Show { .. }
            | Self::Children { .. }
            | Self::Stats
            | Self::Blocked
            | Self::Ready { .. }
            | Self::Quickstart
            | Self::Version
            | Self::MergeDriver {
                command: MergeDriverCommands::Show,
            }
            | Self::MergeDriver {
                command: MergeDriverCommands::Run { stdout: true, .. },
            } => true,
            Self::Export {
                output,
                tz_output_default,
                ..
            } => output.is_none() && !tz_output_default,
            Self::Dep { command } => match command {
                DepCommands::List { .. } | DepCommands::Tree { .. } | DepCommands::Cycles => true,
                DepCommands::Add { .. } | DepCommands::Remove { .. } => false,
            },
            Self::Label { command } => match command {
                LabelCommands::List { .. } | LabelCommands::ListAll => true,
                LabelCommands::Add { .. } | LabelCommands::Remove { .. } => false,
            },
            Self::Config { command } => match command {
                ConfigCommands::Get { .. } | ConfigCommands::List => true,
                ConfigCommands::Set { .. } | ConfigCommands::Unset { .. } => false,
            },
            Self::Triage { command } => {
                matches!(command, TriageCommands::List | TriageCommands::Show { .. })
            }
            Self::Comments { command } => match command {
                CommentCommands::List { .. } => true,
                CommentCommands::Add { .. } | CommentCommands::Delete { .. } => false,
            },
            Self::Init { .. }
            | Self::Create { .. }
            | Self::Update { .. }
            | Self::Claim { .. }
            | Self::Close { .. }
            | Self::Reopen { .. }
            | Self::Rename { .. }
            | Self::RenamePrefix { .. }
            | Self::Sync { .. }
            | Self::Migrate { .. }
            | Self::MergeDriver { .. } => false,
        }
    }
}

#[derive(Subcommand)]
enum MergeDriverCommands {
    /// Merge one file (invoked by git as `merge.tz.driver`). Writes the result to
    /// OURS and exits 0 when clean, 1 when conflict hunks were written.
    Run {
        /// Common ancestor version (git's %O)
        base: PathBuf,
        /// Our version, overwritten with the result (git's %A)
        ours: PathBuf,
        /// Their version (git's %B)
        theirs: PathBuf,
        /// Conflict marker length (git's %L)
        #[arg(long, default_value_t = 7)]
        marker_size: usize,
        /// Repository path of the merged file (git's %P); selects issue,
        /// comment, or plain-text merging. Defaults to OURS.
        #[arg(long)]
        path: Option<PathBuf>,
        /// Print the merge result instead of overwriting OURS
        #[arg(long)]
        stdout: bool,
    },
    /// Register the driver in git config and route tazk files to it in
    /// .gitattributes
    Install {
        /// Executable git should run as the driver
        #[arg(long, default_value = "tz")]
        command: String,
        /// Write the driver to the user's global git config instead of the repository's
        #[arg(long)]
        global: bool,
        /// Do not modify .gitattributes
        #[arg(long)]
        no_gitattributes: bool,
    },
    /// Print the git config and .gitattributes lines the driver needs
    Show,
}

#[derive(Subcommand)]
enum DepCommands {
    /// Add a dependency
    Add {
        /// Issue that has the dependency
        issue_id: String,

        /// Issue that issue_id has the dependency on
        #[arg(long = "target", value_name = "DEPENDENCY_ID")]
        dependency_id: String,

        /// Dependency type: blocked_by, related_to, child_of, discovered_from, tracks
        #[arg(short = 't', long, default_value = "blocked_by")]
        r#type: DependencyType,
    },

    /// Remove a dependency
    Remove {
        /// Issue that has the dependency
        issue_id: String,

        /// Dependency to remove from issue_id
        #[arg(long = "target", value_name = "DEPENDENCY_ID")]
        dependency_id: String,
    },

    /// List dependencies or dependents
    List {
        /// Issue IDs to inspect
        issue_ids: Vec<String>,

        /// Direction: down (dependencies) or up (dependents)
        #[arg(long, default_value = "down")]
        direction: String,

        /// Filter by dependency type
        #[arg(short = 't', long = "type")]
        r#type: Option<DependencyType>,
    },

    /// Show dependency tree
    Tree {
        /// Issue ID to show tree for (supports shorthand: "14" expands to "prefix-14")
        issue_id: String,

        /// Maximum tree depth to display (safety limit)
        #[arg(short = 'd', long, default_value = "50")]
        max_depth: usize,

        /// Show all paths to nodes (no deduplication for diamond dependencies)
        #[arg(long)]
        show_all_paths: bool,
    },

    /// Detect dependency cycles
    Cycles,
}

#[derive(Subcommand)]
enum LabelCommands {
    /// Add a label to one or more issues
    Add {
        /// Issue IDs followed by the label to add
        #[arg(required = true, num_args = 2..)]
        args: Vec<String>,
    },

    /// Remove a label from one or more issues
    Remove {
        /// Issue IDs followed by the label to remove
        #[arg(required = true, num_args = 2..)]
        args: Vec<String>,
    },

    /// List labels for an issue
    List { issue_id: String },

    /// List all unique labels
    ListAll,
}

#[derive(Subcommand)]
enum ConfigCommands {
    /// Get a configuration value
    Get { key: String },

    /// Set a configuration value
    Set { key: String, value: String },

    /// Delete a configuration value (currently sets it empty)
    Unset { key: String },

    /// List all configuration values
    List,
}

#[derive(Subcommand)]
enum TriageCommands {
    /// Report a triage item
    ///
    /// The item's text is TEXT followed, after a blank line, by anything piped
    /// on stdin. At least one must be non-empty. Pipe longer material, such as
    /// external references, logs or review output:
    ///
    ///   gh pr view 12 --json url -q .url | tz triage add "Flaky login test"
    ///
    /// Piping also keeps the shell from expanding backticks and `$(...)` in
    /// prose (see `tz create --help`). stdin is read only when it is not a
    /// terminal; if it is a pipe that never closes, the command waits for it,
    /// so redirect stdin from /dev/null in such environments.
    Add {
        /// Report text
        #[arg(allow_hyphen_values = true)]
        text: Option<String>,
    },

    /// List triage item file names, sorted by name (creation time, to the second)
    List,

    /// Print a triage item's text
    Show {
        /// Item file name (.md optional)
        name: String,
    },

    /// Edit a triage item's text
    ///
    /// Same rules as `tz update --search/--replace/--append`, applied to the
    /// whole item. Give either --search with --replace, or --append.
    #[command(group(
        clap::ArgGroup::new("edit")
            .required(true)
            .multiple(false)
            .args(["search", "append"])
    ))]
    Update {
        /// Item file name (.md optional)
        name: String,

        /// Find this exact text and swap it for --replace. By default it must
        /// match exactly once. Requires --replace.
        #[arg(long, allow_hyphen_values = true, requires = "replace")]
        search: Option<String>,

        /// Replacement text for --search.
        #[arg(long, allow_hyphen_values = true, requires = "search")]
        replace: Option<String>,

        /// With --search, replace every occurrence instead of requiring the
        /// search text to match exactly once.
        #[arg(long, requires = "search")]
        replace_all: bool,

        /// Append this text as a new paragraph.
        #[arg(
            long,
            allow_hyphen_values = true,
            conflicts_with_all = ["search", "replace", "replace_all"]
        )]
        append: Option<String>,
    },

    /// Delete triage items
    ///
    /// All named items must exist; otherwise none is deleted.
    Rm {
        /// Item file names (.md optional)
        #[arg(required = true)]
        names: Vec<String>,
    },

    /// Create one issue from one or more triage items, then delete them
    ///
    /// --title and --role are required; priority and type default as in
    /// `tz create` (2, task). Without a description flag, the issue's
    /// description is the items' text, in the order given, separated by `---`
    /// lines. The issue's notes record the item names, so the originals can be
    /// found in git history. The issue is created and the items deleted
    /// together: if anything fails, nothing changes.
    Promote {
        /// Item file names (.md optional)
        #[arg(required = true)]
        names: Vec<String>,

        /// Issue title
        #[arg(long, required = true, allow_hyphen_values = true)]
        title: String,

        /// Role the issue is for: human, agent (required)
        #[arg(short = 'r', long, required = true)]
        role: Role,

        /// Priority (0-4, 0=highest)
        #[arg(short, long, default_value = "2")]
        priority: i32,

        /// Issue type: bug, feature, task, epic, chore
        #[arg(
            short = 't',
            long = "issue-type",
            visible_alias = "type",
            default_value = "task"
        )]
        issue_type: IssueType,

        /// Description (default: the items' text)
        #[arg(short, long, allow_hyphen_values = true)]
        description: Option<String>,

        /// Read the description from a FILE, or from stdin when given `-`.
        #[arg(
            long = "description-file",
            value_name = "PATH",
            conflicts_with = "description"
        )]
        description_file: Option<String>,

        /// Design notes
        #[arg(long, allow_hyphen_values = true)]
        design: Option<String>,

        /// Acceptance criteria
        #[arg(long, allow_hyphen_values = true)]
        acceptance: Option<String>,

        /// Assignee
        #[arg(short = 'a', long)]
        assignee: Option<String>,

        /// Effort estimate from 1 to 5 (5 is the most effort)
        #[arg(long, value_parser = clap::value_parser!(u8).range(MIN_EFFORT as i64..=MAX_EFFORT as i64))]
        effort: Option<u8>,

        /// Labels (can be specified multiple times)
        #[arg(short, long)]
        label: Vec<String>,

        /// Comma-separated labels
        #[arg(long = "labels")]
        labels: Vec<String>,

        /// External reference
        #[arg(long)]
        external_ref: Option<String>,

        /// Dependencies (comma-separated). Same formats as `tz create --deps`.
        #[arg(long)]
        deps: Option<String>,

        /// Parent issue ID for hierarchical child (e.g., 'tz-a3f8e9')
        #[arg(long)]
        parent: Option<String>,
    },

    /// Add triage items to an existing issue as comments, then delete them
    ///
    /// Each item becomes one comment, in the order given. The comments are
    /// added and the items deleted together: if anything fails, nothing
    /// changes.
    Attach {
        /// Item file names (.md optional)
        #[arg(required = true)]
        names: Vec<String>,

        /// Issue to comment on
        #[arg(long, required = true)]
        to: String,

        /// Comment author
        #[arg(long, required = true)]
        author: String,
    },
}

#[derive(Subcommand)]
enum CommentCommands {
    /// Add a comment to an issue
    Add {
        issue_id: String,

        /// Comment body
        #[arg(short, long, allow_hyphen_values = true)]
        body: String,

        /// Comment author
        #[arg(long, required = true)]
        author: String,
    },

    /// List comments for an issue
    List { issue_id: String },

    /// Delete one or more comments from an issue by comment ID
    Delete {
        issue_id: String,

        /// Comment ID(s) to delete, as shown by `tz comments list`
        comment_ids: Vec<String>,
    },
}

#[derive(serde::Serialize)]
struct ShowCommentView<'a> {
    #[serde(flatten)]
    stored: &'a Comment,
    timestamp: String,
}

#[derive(serde::Serialize)]
struct DepListRow {
    id: String,
    issue_id: String,
    depends_on_id: String,
    dependency_type: String,
    #[serde(rename = "type")]
    dep_type: String,
}

impl<'a> From<&'a Comment> for ShowCommentView<'a> {
    fn from(comment: &'a Comment) -> Self {
        Self {
            stored: comment,
            timestamp: comment.created_at.to_rfc3339(),
        }
    }
}

fn should_color_stdout() -> bool {
    std::io::stdout().is_terminal()
        && env::var_os("NO_COLOR").is_none()
        && env::var("CLICOLOR").map(|v| v != "0").unwrap_or(true)
        && env::var("TERM").map(|v| v != "dumb").unwrap_or(true)
}

fn print_issue_show(issue: &Issue, comments: &[Comment], color: bool) -> Result<()> {
    print_issue_metadata(issue, color);
    let markdown = issue_show_markdown(issue, comments);
    if markdown.trim().is_empty() {
        return Ok(());
    }

    println!();
    if color && print_markdown_with_external_highlighter(&markdown)? {
        return Ok(());
    }
    print!(
        "{}",
        if color {
            colorize_markdown_fallback(&markdown)
        } else {
            markdown
        }
    );
    Ok(())
}

fn print_issue_metadata(issue: &Issue, color: bool) {
    println!(
        "{} {}",
        style_label("ID:", color),
        style_value(&issue.id, color)
    );
    println!(
        "{} {}",
        style_label("Title:", color),
        style_title(&issue.title, color)
    );
    println!(
        "{} {}",
        style_label("Status:", color),
        style_status(issue.status.as_str(), color)
    );
    println!("{} {}", style_label("Priority:", color), issue.priority);
    println!("{} {}", style_label("Type:", color), issue.issue_type);
    if let Some(external_ref) = &issue.external_ref {
        println!(
            "{} {}",
            style_label("External ref:", color),
            style_value(external_ref, color)
        );
    }
    if !issue.assignee.is_empty() {
        println!("{} {}", style_label("Assignee:", color), issue.assignee);
    }
    if let Some(role) = issue.role {
        println!("{} {}", style_label("Role:", color), role);
    }
    if let Some(effort) = issue.effort {
        println!("{} {}", style_label("Effort:", color), effort);
    }
    if !issue.labels.is_empty() {
        println!(
            "{} {}",
            style_label("Labels:", color),
            issue.labels.join(", ")
        );
    }
}

fn issue_show_markdown(issue: &Issue, comments: &[Comment]) -> String {
    let mut out = String::new();
    push_markdown_section(
        &mut out,
        "Description",
        if issue.description.trim().is_empty() {
            "_No description._"
        } else {
            &issue.description
        },
    );
    if !issue.design.trim().is_empty() {
        push_markdown_section(&mut out, "Design", &issue.design);
    }
    push_markdown_section(
        &mut out,
        "Notes",
        if issue.notes.trim().is_empty() {
            "_No notes._"
        } else {
            &issue.notes
        },
    );
    if !issue.acceptance_criteria.trim().is_empty() {
        push_markdown_section(&mut out, "Acceptance Criteria", &issue.acceptance_criteria);
    }
    if !issue.depends_on.is_empty() {
        let mut deps = issue.depends_on.iter().collect::<Vec<_>>();
        deps.sort_by(|a, b| a.0.cmp(b.0));
        let body = deps
            .into_iter()
            .map(|(dep_id, dep_type)| format!("- `{}` ({})", dep_id, dep_type))
            .collect::<Vec<_>>()
            .join("\n");
        push_markdown_section(&mut out, "Dependencies", &body);
    }
    push_markdown_section(&mut out, "Comments", &comments_markdown(comments));
    out
}

fn push_markdown_section(out: &mut String, heading: &str, body: &str) {
    if !out.is_empty() {
        out.push('\n');
    }
    out.push_str(heading);
    out.push('\n');
    out.push_str(&"=".repeat(heading.chars().count()));
    out.push_str("\n\n");
    out.push_str(body.trim());
    out.push('\n');
}

fn comments_markdown(comments: &[Comment]) -> String {
    if comments.is_empty() {
        return "_No comments._".to_string();
    }

    comments
        .iter()
        .map(|comment| {
            format!(
                "### {} at {}\n\n{}",
                comment.author,
                comment.created_at.to_rfc3339(),
                comment.body.trim()
            )
        })
        .collect::<Vec<_>>()
        .join("\n\n")
}

fn split_label_args(labels: Vec<String>) -> Vec<String> {
    labels
        .into_iter()
        .flat_map(|label| split_label_csv(&label))
        .collect()
}

fn split_label_csv(labels: &str) -> Vec<String> {
    labels
        .split(',')
        .map(str::trim)
        .filter(|label| !label.is_empty())
        .map(ToString::to_string)
        .collect()
}

fn split_label_command_args(mut args: Vec<String>) -> Result<(Vec<String>, String)> {
    let label = args
        .pop()
        .ok_or_else(|| anyhow::anyhow!("Label command requires issue IDs and a label"))?;
    if args.is_empty() {
        anyhow::bail!("Label command requires at least one issue ID");
    }
    Ok((args, label))
}

fn print_markdown_with_external_highlighter(markdown: &str) -> Result<bool> {
    for program in ["batcat", "bat"] {
        let mut child = match ProcessCommand::new(program)
            .args([
                "--language",
                "markdown",
                "--style",
                "plain",
                "--color",
                "always",
                "--paging",
                "never",
            ])
            .stdin(Stdio::piped())
            .stdout(Stdio::inherit())
            .stderr(Stdio::null())
            .spawn()
        {
            Ok(child) => child,
            Err(_) => continue,
        };

        if let Some(stdin) = child.stdin.as_mut() {
            stdin
                .write_all(markdown.as_bytes())
                .context("Failed to write markdown to highlighter")?;
        }
        let status = child
            .wait()
            .with_context(|| format!("Failed to wait for {}", program))?;
        if status.success() {
            return Ok(true);
        }
    }
    Ok(false)
}

fn colorize_markdown_fallback(markdown: &str) -> String {
    markdown
        .lines()
        .map(|line| {
            if line.chars().all(|c| c == '=') && !line.is_empty() {
                format!("\x1b[36;1m{}\x1b[0m", line)
            } else if line.starts_with("### ") {
                format!("\x1b[35;1m{}\x1b[0m", line)
            } else {
                line.to_string()
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
        + "\n"
}

fn style_label(text: &str, color: bool) -> String {
    if color {
        format!("\x1b[36;1m{}\x1b[0m", text)
    } else {
        text.to_string()
    }
}

fn style_title(text: &str, color: bool) -> String {
    if color {
        format!("\x1b[1m{}\x1b[0m", text)
    } else {
        text.to_string()
    }
}

fn style_value(text: &str, color: bool) -> String {
    if color {
        format!("\x1b[34m{}\x1b[0m", text)
    } else {
        text.to_string()
    }
}

fn style_status(text: &str, color: bool) -> String {
    if !color {
        return text.to_string();
    }
    let code = match text {
        "open" => "32",
        "in_progress" => "33",
        "closed" => "90",
        _ => "37",
    };
    format!("\x1b[{}m{}\x1b[0m", code, text)
}

/// Print a dependency tree in a visual format
fn print_dependency_tree(node: &types::TreeNode, depth: usize, prefix: &str, is_last: bool) {
    // Print the current node
    let connector = if depth == 0 {
        ""
    } else if is_last {
        "└── "
    } else {
        "├── "
    };

    let dep_type_str = if let Some(ref dt) = node.dep_type {
        format!(" ({})", dt)
    } else {
        String::new()
    };

    let suffix = if node.is_cycle {
        " [CYCLE DETECTED]"
    } else if node.depth_exceeded {
        " [MAX DEPTH EXCEEDED]"
    } else {
        ""
    };

    println!(
        "{}{}{}: {} [{}] (P{}){}{}",
        prefix, connector, node.id, node.title, node.status, node.priority, dep_type_str, suffix
    );

    // Don't recurse if cycle or depth exceeded
    if node.is_cycle || node.depth_exceeded {
        return;
    }

    // Print children
    let child_prefix = if depth == 0 {
        String::new()
    } else if is_last {
        format!("{}    ", prefix)
    } else {
        format!("{}│   ", prefix)
    };

    for (i, child) in node.children.iter().enumerate() {
        let is_last_child = i == node.children.len() - 1;
        print_dependency_tree(child, depth + 1, &child_prefix, is_last_child);
    }
}

/// Resolve an issue body from either an inline argument or a file/stdin.
///
/// `--description-file -` reads stdin. This exists because passing prose as an
/// inline shell argument lets the SHELL expand backticks and `$(...)` before
/// tazk receives it: the command then stores a silently truncated body and
/// exits 0. tazk cannot detect that -- by the time the string arrives it is
/// already valid and already wrong -- so the only real fix is to keep the shell
/// out of the path. Four separate agents hit that footgun in a single day, all
/// of whom knew the rule, because this safe path did not exist.
fn resolve_body(inline: Option<String>, from_file: Option<String>) -> Result<Option<String>> {
    match from_file {
        None => Ok(inline),
        Some(path) => {
            use std::io::Read;
            let text = if path == "-" {
                let mut buf = String::new();
                std::io::stdin()
                    .read_to_string(&mut buf)
                    .context("Failed to read description from stdin")?;
                buf
            } else {
                std::fs::read_to_string(&path)
                    .with_context(|| format!("Failed to read description from {path}"))?
            };
            Ok(Some(text))
        }
    }
}

/// Run a `tz triage` subcommand.
fn run_triage_command(storage: &Storage, command: TriageCommands, json: bool) -> Result<()> {
    match command {
        TriageCommands::Add { text } => {
            let piped = read_piped_stdin()?;
            let body = triage::compose_body(&[text.as_deref().unwrap_or(""), &piped]);
            if body.is_empty() {
                anyhow::bail!(
                    "A triage item needs some text: give it as an argument or pipe it on stdin"
                );
            }
            let item = storage.add_triage_item(&body)?;
            if json {
                println!("{}", serde_json::to_string_pretty(&item)?);
            } else {
                println!("Created triage item: {}", item.name);
                report_stored_body("text", &item.body);
            }
        }
        TriageCommands::List => {
            let items = storage.list_triage_items()?;
            if json {
                println!("{}", serde_json::to_string_pretty(&items)?);
            } else {
                for item in items {
                    println!("{}", item.name);
                }
            }
        }
        TriageCommands::Show { name } => {
            let item = storage.get_triage_item(&name)?;
            if json {
                println!("{}", serde_json::to_string_pretty(&item)?);
            } else {
                print!("{}", item.body);
                if !item.body.ends_with('\n') {
                    println!();
                }
            }
        }
        TriageCommands::Update {
            name,
            search,
            replace,
            replace_all,
            append,
        } => {
            // clap guarantees exactly one mode: --search (with --replace) or
            // --append.
            let item = match (search, append) {
                (Some(search), _) => storage.search_replace_triage_item(
                    &name,
                    &search,
                    &replace.unwrap_or_default(),
                    replace_all,
                )?,
                (None, Some(append)) => storage.append_to_triage_item(&name, &append)?,
                (None, None) => anyhow::bail!("Give --search/--replace or --append"),
            };
            if json {
                println!("{}", serde_json::to_string_pretty(&item)?);
            } else {
                println!("Updated triage item: {}", item.name);
                report_stored_body("text", &item.body);
            }
        }
        TriageCommands::Rm { names } => {
            let removed = storage.remove_triage_items(&names)?;
            if json {
                println!("{}", serde_json::to_string_pretty(&removed)?);
            } else {
                for name in removed {
                    println!("Removed triage item: {name}");
                }
            }
        }
        TriageCommands::Promote {
            names,
            title,
            role,
            priority,
            issue_type,
            description,
            description_file,
            design,
            acceptance,
            assignee,
            effort,
            label,
            labels,
            external_ref,
            deps,
            parent,
        } => {
            let description = resolve_body(description, description_file)?.unwrap_or_default();
            let mut all_labels = label;
            all_labels.extend(split_label_args(labels));
            let issue = storage.promote_triage_items(
                &names,
                NewIssue {
                    title,
                    description,
                    design,
                    acceptance,
                    priority,
                    issue_type,
                    assignee,
                    labels: all_labels,
                    external_ref,
                    id: None,
                    deps: parse_deps(deps, parent),
                    role: Some(role),
                    effort,
                },
            )?;
            if json {
                println!("{}", serde_json::to_string_pretty(&issue)?);
            } else {
                println!("Created issue: {}", issue.id);
                report_stored_body("description", &issue.description);
                println!("  {}", issue.notes);
            }
        }
        TriageCommands::Attach { names, to, author } => {
            let attached = storage.attach_triage_items(&names, &to, &author)?;
            if json {
                let value: Vec<_> = attached
                    .iter()
                    .map(|(name, comment)| serde_json::json!({ "name": name, "comment": comment }))
                    .collect();
                println!("{}", serde_json::to_string_pretty(&value)?);
            } else {
                for (name, comment) in attached {
                    println!("Attached {name} to {to} as comment {}", comment.id);
                }
            }
        }
    }
    Ok(())
}

/// Everything on stdin when it is piped or redirected from a file; empty when
/// it is a terminal. Blocks until the writer closes the pipe.
fn read_piped_stdin() -> Result<String> {
    use std::io::Read;
    let mut stdin = std::io::stdin();
    if stdin.is_terminal() {
        return Ok(String::new());
    }
    let mut buf = String::new();
    stdin
        .read_to_string(&mut buf)
        .context("Failed to read stdin (it must be UTF-8 text)")?;
    Ok(buf)
}

/// Parse `--deps` / `--parent` into dependency edges.
///
/// Supports two formats:
/// 1. Simple: "tz-1,tz-2" (defaults to 'blocked_by' type)
/// 2. Advanced: "blocked_by:tz-1,related_to:tz-2,discovered_from:tz-3"
///
/// A parent is added as a `child_of` dependency.
fn parse_deps(deps: Option<String>, parent: Option<String>) -> Vec<(String, DependencyType)> {
    let mut parsed_deps: Vec<(String, DependencyType)> = if let Some(deps_str) = deps {
        deps_str
            .split(',')
            .filter_map(|s| {
                let s = s.trim();
                if s.is_empty() {
                    return None;
                }

                // Check if it contains a colon (advanced format)
                if let Some(colon_idx) = s.find(':') {
                    let (type_str, id) = s.split_at(colon_idx);
                    let id = id[1..].trim(); // Skip the colon

                    // Parse the dependency type
                    match type_str.parse::<DependencyType>() {
                        Ok(dep_type) => Some((id.to_string(), dep_type)),
                        Err(_) => {
                            eprintln!(
                                "Warning: Invalid dependency type '{}', skipping '{}'",
                                type_str, s
                            );
                            None
                        }
                    }
                } else {
                    // Simple format: just the ID, default to BlockedBy
                    Some((s.to_string(), DependencyType::BlockedBy))
                }
            })
            .collect()
    } else {
        Vec::new()
    };

    // Add parent as a child_of dependency if specified
    if let Some(parent_id) = parent {
        parsed_deps.push((parent_id, DependencyType::ChildOf));
    }
    parsed_deps
}

/// Report what was actually STORED, not merely that the write succeeded.
///
/// The character count is the load-bearing part: a body mangled by shell
/// expansion comes back conspicuously short, and a count survives being piped
/// through `head`/`tail` in a way a multi-line echo does not.
fn report_stored_body(field: &str, body: &str) {
    let chars = body.chars().count();
    let preview: String = body
        .chars()
        .take(140)
        .collect::<String>()
        .replace('\n', " ");
    let ellipsis = if chars > 140 { " ..." } else { "" };
    println!("  stored {field}: {chars} characters");
    if chars > 0 {
        println!("  begins: {preview}{ellipsis}");
    }
}

fn main() {
    if let Err(e) = run() {
        eprintln!("Error: {:#}", e);
        std::process::exit(1);
    }
}

/// In-memory issue filters shared by `list` and `ready`. The storage layer
/// handles status/priority/type/assignee; everything here is a post-query
/// `retain` so both commands filter identically.
struct IssueFilters<'a> {
    /// Must have ALL specified labels.
    labels: &'a [String],
    /// Restrict to a comma-separated set of exact issue IDs.
    id: Option<&'a str>,
    /// Case-insensitive title substring.
    title: Option<&'a str>,
    /// Only direct children of this parent issue.
    parent: Option<&'a str>,
    /// Only issues with this role.
    role: Option<Role>,
}

/// Parse priority filters into a flat list, shared by `list` and `ready`. The
/// flag is repeatable and each value may itself be comma-separated, so
/// `-p 0 -p 1`, `-p 0,1`, and `-p 0 -p 1,2` are all accepted. Returns None when
/// no priority filter was supplied.
fn parse_priority_filters(values: &[String]) -> Result<Option<Vec<i32>>> {
    let mut priorities = Vec::new();
    for value in values {
        for part in value.split(',') {
            let part = part.trim();
            if part.is_empty() {
                continue;
            }
            priorities.push(part.parse::<i32>().context("Invalid priority value")?);
        }
    }

    if priorities.is_empty() {
        Ok(None)
    } else {
        Ok(Some(priorities))
    }
}

/// Print issues grouped by priority with a boxed header per group. Shared by
/// `list` and `ready` (`--group-priority`).
fn print_issues_grouped_by_priority(issues: &[Issue]) {
    // Group issues by priority using BTreeMap for sorted keys
    let mut groups: BTreeMap<i32, Vec<&Issue>> = BTreeMap::new();
    for issue in issues {
        groups.entry(issue.priority).or_default().push(issue);
    }

    for (priority, group_issues) in groups {
        let header_text = format!("Priority {}", priority);
        let header_width = 60;
        let padding = (header_width - header_text.len() - 2) / 2;
        println!("{}", "=".repeat(header_width));
        println!(
            "|{}{}{}|",
            " ".repeat(padding),
            header_text,
            " ".repeat(header_width - padding - header_text.len() - 2)
        );
        println!("{}", "=".repeat(header_width));

        for issue in group_issues {
            println!("{}: {} [{}]", issue.id, issue.title, issue.status);
        }
        println!();
    }
}

impl IssueFilters<'_> {
    fn apply(&self, issues: &mut Vec<Issue>) {
        if !self.labels.is_empty() {
            issues.retain(|issue| self.labels.iter().all(|label| issue.labels.contains(label)));
        }

        if let Some(id_filter) = self.id {
            let target_ids: Vec<&str> = id_filter.split(',').map(str::trim).collect();
            issues.retain(|issue| target_ids.contains(&issue.id.as_str()));
        }

        if let Some(title_filter) = self.title {
            let title_lower = title_filter.to_lowercase();
            issues.retain(|issue| issue.title.to_lowercase().contains(&title_lower));
        }

        if let Some(role) = self.role {
            issues.retain(|issue| issue.role == Some(role));
        }

        if let Some(parent_id) = self.parent {
            issues.retain(|issue| {
                issue
                    .depends_on
                    .get(parent_id)
                    .is_some_and(|dep_type| *dep_type == DependencyType::ChildOf)
            });
        }
    }
}

fn run_merge_driver_command(command: MergeDriverCommands) -> Result<()> {
    match command {
        MergeDriverCommands::Run {
            base,
            ours,
            theirs,
            marker_size,
            path,
            stdout,
        } => {
            let outcome = merge_driver::run_driver(&merge_driver::DriverRun {
                base: &base,
                ours: &ours,
                theirs: &theirs,
                path: path.as_deref(),
                size: diff3::MarkerSize::new(marker_size),
                stdout,
            })?;
            if outcome == merge_driver::DriverOutcome::Conflicted {
                std::process::exit(1);
            }
            Ok(())
        }
        MergeDriverCommands::Install {
            command,
            global,
            no_gitattributes,
        } => {
            let report = merge_driver::install(&merge_driver::InstallOptions {
                executable: &command,
                global,
                skip_gitattributes: no_gitattributes,
            })?;
            for line in report {
                println!("{line}");
            }
            println!("Installed the tazk merge driver.");
            Ok(())
        }
        MergeDriverCommands::Show => {
            println!(
                "git config merge.{}.driver '{}'",
                merge_driver::DRIVER_NAME,
                merge_driver::driver_command("tz")
            );
            println!("# .gitattributes");
            for line in merge_driver::gitattributes_lines() {
                println!("{line}");
            }
            Ok(())
        }
    }
}

fn run() -> Result<()> {
    let cli = Cli::parse();
    let readonly = cli.global_opts.readonly;
    anyhow::ensure!(
        !readonly || cli.command.is_read_only(),
        "--readonly rejects commands that can modify files or remote issues"
    );

    if let Some(directory) = &cli.global_opts.directory {
        env::set_current_dir(directory)
            .with_context(|| format!("Failed to change directory to {}", directory.display()))?;
    }

    // Extract fields needed for get_storage before matching on cli.command
    // This avoids borrowing issues when we try to call get_storage(tz_dir, readonly) inside match arms
    let tz_dir = &cli.global_opts.tz_dir;
    let json = cli.global_opts.json;
    let tz_no_cmd_logging = cli.global_opts.tz_no_cmd_logging || readonly;

    match cli.command {
        Commands::Init {
            prefix,
            tz_hash_ids,
            tz_issue_layout,
            quiet,
        } => {
            // IMPORTANT: init always creates the primary storage dir in current directory
            // It does NOT use find_tazk_dir() or respect the --tz-dir flag
            // This ensures init always initializes in CWD, never in ancestor directories
            if tz_dir.is_some() {
                eprintln!(
                    "Note: 'tz init' always creates {}/ in current directory",
                    PRIMARY_STORAGE_DIR
                );
                eprintln!("      --tz-dir is ignored for 'init'");
            }

            let tazk_dir = PathBuf::from(PRIMARY_STORAGE_DIR);
            let issue_layout = match tz_issue_layout.as_str() {
                "flat" => IssueStorageLayout::Flat,
                "sharded" => IssueStorageLayout::Sharded,
                other => anyhow::bail!(
                    "Invalid --tz-issue-layout '{}'. Valid values are: flat, sharded",
                    other
                ),
            };
            let storage = Storage::init(tazk_dir, prefix, tz_hash_ids, issue_layout)?;

            // Log command after successful init
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            if !json && !quiet {
                println!(
                    "Initialized tazk database with prefix: {}",
                    storage.get_prefix()?
                );
            }
            Ok(())
        }

        Commands::Create {
            title,
            title_flag,
            priority,
            issue_type,
            description,
            description_file,
            design,
            acceptance,
            assignee,
            role,
            effort,
            label,
            labels,
            external_ref,
            id,
            deps,
            parent,
            force: _force,
            file,
        } => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            // Handle bulk creation from file
            if let Some(_file_path) = file {
                anyhow::bail!(
                    "--file flag not yet implemented. Bulk creation from markdown files coming soon."
                );
            }

            // Determine title from either positional argument or --title flag
            let actual_title = match (title, title_flag) {
                (Some(t), None) => t,
                (None, Some(t)) => t,
                (Some(_), Some(_)) => {
                    anyhow::bail!("Cannot specify both positional title and --title flag");
                }
                (None, None) => {
                    anyhow::bail!("Title is required. Use positional argument or --title flag.");
                }
            };

            let parsed_deps = parse_deps(deps, parent);

            let mut all_labels = label;
            all_labels.extend(split_label_args(labels));

            // Prefer a file/stdin body when given; the shell never touches it.
            let description =
                resolve_body(Some(description), description_file)?.unwrap_or_default();

            let issue = storage.create_issue(
                actual_title,
                description.clone(),
                design,
                acceptance,
                priority,
                issue_type,
                assignee,
                all_labels,
                external_ref,
                id,
                parsed_deps,
                Some(role),
                effort,
            )?;

            if json {
                println!("{}", serde_json::to_string_pretty(&issue)?);
            } else {
                println!("Created issue: {}", issue.id);
                // Report what was STORED, not merely that the write succeeded.
                report_stored_body("description", &description);
            }
            Ok(())
        }

        Commands::Triage { command } => {
            let storage = get_storage(tz_dir, readonly)?;

            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            run_triage_command(&storage, command, json)
        }

        Commands::List {
            status,
            priority,
            r#type,
            assignee,
            role,
            labels,
            id,
            title,
            parent,
            limit,
            group_priority,
        } => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            // Parse priority filters (repeatable and/or comma-separated)
            let priority_list = parse_priority_filters(&priority)?;

            let status_filter = match status.as_deref() {
                None | Some("all") => None,
                Some(value) => Some(value.parse::<Status>()?),
            };

            let mut issues = storage.list_issues(
                status_filter,
                priority_list,
                r#type,
                assignee.as_deref(),
                None,
            )?;

            // Apply in-memory filters shared with `ready`
            IssueFilters {
                labels: &labels,
                id: id.as_deref(),
                title: title.as_deref(),
                parent: parent.as_deref(),
                role,
            }
            .apply(&mut issues);

            // Apply limit if specified
            if let Some(limit_val) = limit {
                if limit_val > 0 {
                    issues.truncate(limit_val);
                }
            }

            if json {
                println!("{}", serde_json::to_string_pretty(&issues)?);
            } else if group_priority {
                print_issues_grouped_by_priority(&issues);
            } else {
                // Standard output
                for issue in issues {
                    println!(
                        "{}: {} [{}] (priority: {})",
                        issue.id, issue.title, issue.status, issue.priority
                    );
                }
            }
            Ok(())
        }

        Commands::Show { issue_ids } => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            if issue_ids.is_empty() {
                anyhow::bail!("No issue IDs provided. Usage: tz show <issue-id> [issue-ids...]");
            }

            let prefix = storage.get_prefix()?;
            let mut issues = Vec::new();

            // Normalize issue IDs (expand numeric shorthand like "14" -> "prefix-14")
            for id_str in &issue_ids {
                let normalized_id = if id_str.parse::<u32>().is_ok() {
                    format!("{}-{}", prefix, id_str)
                } else {
                    id_str.clone()
                };

                let issue = storage
                    .get_issue(&normalized_id)?
                    .ok_or_else(|| anyhow::anyhow!("Issue not found: {}", normalized_id))?;
                issues.push(issue);
            }

            if json {
                let issues_with_comments = issues
                    .iter()
                    .map(|issue| {
                        let mut value = serde_json::to_value(issue)?;
                        if let serde_json::Value::Object(ref mut object) = value {
                            let comments = storage.list_comments(&issue.id)?;
                            let comment_views = comments
                                .iter()
                                .map(ShowCommentView::from)
                                .collect::<Vec<_>>();
                            object.insert(
                                "comments".to_string(),
                                serde_json::to_value(comment_views)?,
                            );
                        }
                        Ok(value)
                    })
                    .collect::<Result<Vec<_>>>()?;
                println!("{}", serde_json::to_string_pretty(&issues_with_comments)?);
            } else {
                let use_color = should_color_stdout();
                for (idx, issue) in issues.iter().enumerate() {
                    if idx > 0 {
                        println!("\n{}", "=".repeat(70));
                        println!();
                    }
                    let comments = storage.list_comments(&issue.id)?;
                    print_issue_show(issue, &comments, use_color)?;
                }
            }
            Ok(())
        }

        Commands::Children { parent_id } => {
            let storage = get_storage(tz_dir, readonly)?;

            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            let mut children = storage.list_issues(None, None, None, None, None)?;
            children.retain(|issue| {
                issue
                    .depends_on
                    .get(&parent_id)
                    .is_some_and(|dep_type| *dep_type == DependencyType::ChildOf)
            });

            if json {
                println!("{}", serde_json::to_string_pretty(&children)?);
            } else {
                for child in children {
                    println!("{}: {} [{}]", child.id, child.title, child.status);
                }
            }
            Ok(())
        }

        Commands::Update {
            issue_ids,
            priority,
            assignee,
            unassign,
            role,
            clear_role,
            effort,
            clear_effort,
            title,
            description,
            description_file,
            search,
            replace,
            search_field,
            replace_all,
            append,
            design,
            acceptance,
            notes,
            external_ref,
            add_label,
            remove_label,
            set_labels,
        } => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            // Targeted search/replace edit. clap guarantees --search comes with
            // --replace and is mutually exclusive with the wholesale field
            // setters, so this is a self-contained mode.
            if let Some(search) = search {
                let replace = replace.unwrap_or_default();
                let mut updated_issues = Vec::new();
                for issue_id in &issue_ids {
                    let issue = storage.search_replace_issue(
                        issue_id,
                        search_field,
                        &search,
                        &replace,
                        replace_all,
                    )?;
                    updated_issues.push(issue);
                }
                if json {
                    println!("{}", serde_json::to_string_pretty(&updated_issues)?);
                } else {
                    for issue in &updated_issues {
                        println!("Updated issue: {} ({} field)", issue.id, search_field);
                    }
                }
                return Ok(());
            }

            // Targeted append edit. clap guarantees --append is mutually
            // exclusive with --search/--replace and the wholesale field setters, so
            // this is a self-contained mode like search/replace.
            if let Some(append) = append {
                let mut updated_issues = Vec::new();
                for issue_id in &issue_ids {
                    let issue = storage.append_to_issue(issue_id, search_field, &append)?;
                    updated_issues.push(issue);
                }
                if json {
                    println!("{}", serde_json::to_string_pretty(&updated_issues)?);
                } else {
                    for issue in &updated_issues {
                        println!("Appended to issue: {} ({} field)", issue.id, search_field);
                    }
                }
                return Ok(());
            }

            let mut updates = HashMap::new();
            // Retained so the success output can report what was STORED.
            let mut stored_description: Option<String> = None;
            if let Some(p) = priority {
                updates.insert("priority".to_string(), p.to_string());
            }
            if let Some(a) = assignee {
                updates.insert("assignee".to_string(), a);
            }
            if unassign {
                updates.insert("assignee".to_string(), String::new());
            }
            if let Some(r) = role {
                updates.insert("role".to_string(), r.to_string());
            }
            if clear_role {
                updates.insert("role".to_string(), String::new());
            }
            if let Some(e) = effort {
                updates.insert("effort".to_string(), e.to_string());
            }
            if clear_effort {
                updates.insert("effort".to_string(), String::new());
            }
            if let Some(t) = title {
                updates.insert("title".to_string(), t);
            }
            // Prefer a file/stdin body when given; the shell never touches it.
            let description = resolve_body(description, description_file)?;
            if let Some(d) = description {
                stored_description = Some(d.clone());
                updates.insert("description".to_string(), d);
            }
            if let Some(d) = design {
                updates.insert("design".to_string(), d);
            }
            if let Some(a) = acceptance {
                updates.insert("acceptance_criteria".to_string(), a);
            }
            if let Some(n) = notes {
                updates.insert("notes".to_string(), n);
            }
            if let Some(e) = external_ref {
                updates.insert("external_ref".to_string(), e);
            }

            // Update all specified issues
            let mut updated_issues = Vec::new();
            for issue_id in &issue_ids {
                let mut issue = storage.update_issue(issue_id, updates.clone())?;

                if let Some(labels) = &set_labels {
                    issue = storage.set_labels(issue_id, split_label_csv(labels))?;
                }
                for label in split_label_args(add_label.clone()) {
                    issue = storage.add_label(issue_id, &label)?;
                }
                for label in split_label_args(remove_label.clone()) {
                    issue = storage.remove_label(issue_id, &label)?;
                }
                updated_issues.push(issue);
            }

            if json {
                println!("{}", serde_json::to_string_pretty(&updated_issues)?);
            } else {
                for issue in &updated_issues {
                    println!("Updated issue: {}", issue.id);
                    // Report what was STORED, not merely that it succeeded.
                    if let Some(body) = stored_description.as_deref() {
                        report_stored_body("description", body);
                    }
                }
            }
            Ok(())
        }

        Commands::Claim {
            issue_ids,
            claim_as,
            release,
            team,
            force,
        } => {
            let storage = get_storage(tz_dir, readonly)?;

            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            if issue_ids.is_empty() {
                anyhow::bail!(
                    "No issue IDs given to {}",
                    if release { "release" } else { "claim" }
                );
            }

            let actor = match team.as_deref() {
                Some(t) if !t.is_empty() => format!("{claim_as}/{t}"),
                _ => claim_as,
            };

            let mut result_issues = Vec::new();
            for issue_id in &issue_ids {
                let issue = if release {
                    storage.release_issue(issue_id, &actor, force)?
                } else {
                    storage.claim_issue(issue_id, &actor, force)?
                };
                result_issues.push(issue);
            }

            if json {
                println!("{}", serde_json::to_string_pretty(&result_issues)?);
            } else {
                for issue in &result_issues {
                    if release {
                        println!("Released {} (was claimed by '{}')", issue.id, actor);
                    } else {
                        print_claim_result(issue);
                    }
                }
            }
            Ok(())
        }

        Commands::Close { issue_ids, reason } => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            // Close all specified issues
            let mut closed_issues = Vec::new();
            for issue_id in &issue_ids {
                let issue = storage.close_issue(issue_id, &reason)?;
                closed_issues.push(issue);
            }

            if json {
                println!("{}", serde_json::to_string_pretty(&closed_issues)?);
            } else {
                for issue in &closed_issues {
                    println!("Closed issue: {}", issue.id);
                }
            }
            Ok(())
        }

        Commands::Reopen {
            issue_ids,
            reason: _,
            role,
        } => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            // Check every issue before changing any, so a missing role doesn't
            // leave a multi-issue reopen half done.
            if role.is_none() {
                let mut missing = Vec::new();
                for issue_id in &issue_ids {
                    if let Some(issue) = storage.get_issue(issue_id)? {
                        if issue.role.is_none() {
                            missing.push(issue.id);
                        }
                    }
                }
                if !missing.is_empty() {
                    anyhow::bail!(
                        "Cannot reopen {}: no role set. Resubmit with --role human|agent",
                        missing.join(", ")
                    );
                }
            }

            let mut reopened = Vec::new();

            for issue_id in issue_ids {
                let issue = storage.reopen_issue(&issue_id, role)?;
                reopened.push(issue);
            }

            if json {
                println!("{}", serde_json::to_string_pretty(&reopened)?);
            } else {
                for issue in reopened {
                    println!("Reopened issue: {}", issue.id);
                }
            }
            Ok(())
        }

        Commands::Rename {
            old_id,
            new_id,
            dry_run,
            repair,
            tz_patch_code,
        } => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            if repair {
                // Repair mode: scan all issues and fix broken references
                let changes = storage.repair_references(dry_run)?;

                if json {
                    println!("{}", serde_json::to_string_pretty(&changes)?);
                } else if dry_run {
                    println!("Dry run - would make the following changes:");
                    for change in &changes {
                        println!("  {}", change);
                    }
                } else if changes.len() == 1 && changes[0] == "No broken references found" {
                    println!("No broken references found");
                } else {
                    println!("Repaired {} broken reference(s)", changes.len());
                    for change in &changes {
                        println!("  {}", change);
                    }
                }
            } else {
                // Rename mode
                let changes = storage.rename_issue(&old_id, &new_id, dry_run)?;

                if json {
                    println!("{}", serde_json::to_string_pretty(&changes)?);
                } else if dry_run {
                    println!("Dry run - would make the following changes:");
                    for change in &changes {
                        println!("  {}", change);
                    }
                } else {
                    println!("Successfully renamed {} to {}", old_id, new_id);
                    if changes.len() > 2 {
                        println!("Updated {} file(s) with references", changes.len() - 2);
                    }

                    // Patch code references if requested
                    if tz_patch_code {
                        if let Err(e) = code_patch::patch_code_for_rename(&old_id, &new_id) {
                            eprintln!("Warning: Code patching failed: {}", e);
                        }
                    }
                }
            }
            Ok(())
        }

        Commands::RenamePrefix {
            new_prefix,
            dry_run,
            force,
        } => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            let changes = storage.rename_prefix(&new_prefix, dry_run, force)?;

            if json {
                println!("{}", serde_json::to_string_pretty(&changes)?);
            } else if dry_run {
                println!("Dry run - would make the following changes:");
                for change in &changes {
                    println!("  {}", change);
                }
            } else {
                println!("Successfully renamed prefix to '{}'", new_prefix);
                println!("Renamed {} issue(s)", changes.len() / 2); // Each issue has 2 changes: file rename + content update
            }
            Ok(())
        }

        Commands::Dep { command } => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            match command {
                DepCommands::Add {
                    issue_id,
                    dependency_id,
                    r#type,
                } => {
                    storage.add_dependency(&issue_id, &dependency_id, r#type)?;

                    if !json {
                        println!(
                            "Added dependency: {} depends on {} ({})",
                            issue_id, dependency_id, r#type
                        );
                    }
                }
                DepCommands::Remove {
                    issue_id,
                    dependency_id,
                } => {
                    storage.remove_dependency(&issue_id, &dependency_id)?;

                    if !json {
                        println!(
                            "Removed dependency: {} no longer depends on {}",
                            issue_id, dependency_id
                        );
                    }
                }
                DepCommands::List {
                    issue_ids,
                    direction,
                    r#type,
                } => {
                    let mut rows = Vec::new();
                    for issue_id in issue_ids {
                        let issue = storage
                            .get_issue(&issue_id)?
                            .ok_or_else(|| anyhow::anyhow!("Issue not found: {}", issue_id))?;

                        match direction.as_str() {
                            "down" => {
                                for (target_id, dep_type) in issue.depends_on {
                                    if r#type.is_none_or(|filter| filter == dep_type) {
                                        let dep_type = dep_type.to_string();
                                        rows.push(DepListRow {
                                            id: target_id.clone(),
                                            issue_id: issue.id.clone(),
                                            depends_on_id: target_id,
                                            dependency_type: dep_type.clone(),
                                            dep_type,
                                        });
                                    }
                                }
                            }
                            "up" => {
                                for dependent in issue.dependents {
                                    let dep_type = dependent
                                        .dep_type
                                        .parse::<DependencyType>()
                                        .unwrap_or(DependencyType::BlockedBy);
                                    if r#type.is_none_or(|filter| filter == dep_type) {
                                        let dep_type = dependent.dep_type;
                                        rows.push(DepListRow {
                                            id: dependent.id.clone(),
                                            issue_id: dependent.id,
                                            depends_on_id: issue.id.clone(),
                                            dependency_type: dep_type.clone(),
                                            dep_type,
                                        });
                                    }
                                }
                            }
                            _ => {
                                anyhow::bail!(
                                    "Invalid direction '{}'. Use 'down' or 'up'",
                                    direction
                                );
                            }
                        }
                    }

                    if json {
                        println!("{}", serde_json::to_string_pretty(&rows)?);
                    } else {
                        for row in rows {
                            println!(
                                "{} depends on {} ({})",
                                row.issue_id, row.depends_on_id, row.dep_type
                            );
                        }
                    }
                }
                DepCommands::Tree {
                    issue_id,
                    max_depth,
                    show_all_paths,
                } => {
                    let tree = storage.get_dependency_tree(&issue_id, max_depth, show_all_paths)?;

                    if json {
                        println!("{}", serde_json::to_string_pretty(&tree)?);
                    } else {
                        print_dependency_tree(&tree, 0, "", true);
                    }
                }
                DepCommands::Cycles => {
                    let cycles = storage.detect_dependency_cycles()?;

                    if json {
                        println!("{}", serde_json::to_string_pretty(&cycles)?);
                    } else if cycles.is_empty() {
                        println!("No dependency cycles detected.");
                    } else {
                        println!("Found {} dependency cycle(s):\n", cycles.len());
                        for (i, cycle) in cycles.iter().enumerate() {
                            println!("Cycle {}:", i + 1);
                            for (j, issue_id) in cycle.iter().enumerate() {
                                if j == cycle.len() - 1 {
                                    println!("  {} -> {} (completes cycle)", issue_id, cycle[0]);
                                } else {
                                    println!("  {} ->", issue_id);
                                }
                            }
                            println!();
                        }
                    }
                }
            }
            Ok(())
        }

        Commands::Label { command } => {
            let storage = get_storage(tz_dir, readonly)?;

            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            match command {
                LabelCommands::Add { args } => {
                    let (issue_ids, label) = split_label_command_args(args)?;
                    let mut updated = Vec::new();
                    for issue_id in issue_ids {
                        updated.push(storage.add_label(&issue_id, &label)?);
                    }
                    if json {
                        println!("{}", serde_json::to_string_pretty(&updated)?);
                    } else {
                        for issue in updated {
                            println!("Added label '{}' to {}", label, issue.id);
                        }
                    }
                }
                LabelCommands::Remove { args } => {
                    let (issue_ids, label) = split_label_command_args(args)?;
                    let mut updated = Vec::new();
                    for issue_id in issue_ids {
                        updated.push(storage.remove_label(&issue_id, &label)?);
                    }
                    if json {
                        println!("{}", serde_json::to_string_pretty(&updated)?);
                    } else {
                        for issue in updated {
                            println!("Removed label '{}' from {}", label, issue.id);
                        }
                    }
                }
                LabelCommands::List { issue_id } => {
                    let issue = storage
                        .get_issue(&issue_id)?
                        .ok_or_else(|| anyhow::anyhow!("Issue not found: {}", issue_id))?;
                    if json {
                        println!("{}", serde_json::to_string_pretty(&issue.labels)?);
                    } else {
                        for label in issue.labels {
                            println!("{}", label);
                        }
                    }
                }
                LabelCommands::ListAll => {
                    let labels = storage.list_all_labels()?;
                    if json {
                        println!("{}", serde_json::to_string_pretty(&labels)?);
                    } else {
                        for label in labels {
                            println!("{}", label);
                        }
                    }
                }
            }
            Ok(())
        }

        Commands::Config { command } => {
            let storage = get_storage(tz_dir, readonly)?;

            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            match command {
                ConfigCommands::Get { key } => {
                    if let Some(value) = storage.get_config_value(&key)? {
                        if json {
                            println!("{}", serde_json::to_string_pretty(&value)?);
                        } else {
                            println!("{}", value);
                        }
                    }
                }
                ConfigCommands::Set { key, value } => {
                    storage.set_config_value(&key, &value)?;
                    if !json {
                        println!("Set {}={}", key, value);
                    }
                }
                ConfigCommands::Unset { key } => {
                    storage.set_config_value(&key, "")?;
                    if !json {
                        println!("Unset {}", key);
                    }
                }
                ConfigCommands::List => {
                    let config = storage
                        .list_config_values()?
                        .into_iter()
                        .collect::<BTreeMap<_, _>>();
                    if json {
                        println!("{}", serde_json::to_string_pretty(&config)?);
                    } else {
                        for (key, value) in config {
                            println!("{}={}", key, value);
                        }
                    }
                }
            }
            Ok(())
        }

        Commands::Comments { command } => {
            let storage = get_storage(tz_dir, readonly)?;

            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            match command {
                CommentCommands::Add {
                    issue_id,
                    body,
                    author,
                } => {
                    let comment = storage.add_comment(&issue_id, &author, &body)?;
                    if json {
                        println!("{}", serde_json::to_string_pretty(&comment)?);
                    } else {
                        println!("Added comment: {}", comment.id);
                    }
                }
                CommentCommands::List { issue_id } => {
                    let comments = storage.list_comments(&issue_id)?;
                    if json {
                        println!("{}", serde_json::to_string_pretty(&comments)?);
                    } else {
                        for comment in comments {
                            println!(
                                "[{} at {}] {}\n{}",
                                comment.author,
                                comment.created_at.to_rfc3339(),
                                comment.id,
                                comment.body
                            );
                        }
                    }
                }
                CommentCommands::Delete {
                    issue_id,
                    comment_ids,
                } => {
                    if comment_ids.is_empty() {
                        anyhow::bail!("No comment IDs given to delete");
                    }
                    let mut deleted = Vec::new();
                    for comment_id in &comment_ids {
                        deleted.push(storage.delete_comment(&issue_id, comment_id)?);
                    }
                    if json {
                        println!("{}", serde_json::to_string_pretty(&deleted)?);
                    } else {
                        for comment in &deleted {
                            println!("Deleted comment: {}", comment.id);
                        }
                    }
                }
            }
            Ok(())
        }

        Commands::Stats => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            let stats = storage.get_stats()?;

            if json {
                println!("{}", serde_json::to_string_pretty(&stats)?);
            } else {
                println!("Total issues: {}", stats.total_issues);
                println!("Open: {}", stats.open_issues);
                println!("In Progress: {}", stats.in_progress_issues);
                println!("Blocked: {}", stats.blocked_issues);
                println!("Closed: {}", stats.closed_issues);
                println!("Ready: {}", stats.ready_issues);
                println!(
                    "Average lead time: {:.1} hours",
                    stats.average_lead_time_hours
                );
            }
            Ok(())
        }

        Commands::Blocked => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            let blocked = storage.get_blocked()?;

            if json {
                println!("{}", serde_json::to_string_pretty(&blocked)?);
            } else {
                for item in blocked {
                    println!(
                        "{}: {} - blocked by: {}",
                        item.issue.id,
                        item.issue.title,
                        item.blocked_by.join(", ")
                    );
                }
            }
            Ok(())
        }

        Commands::Export {
            output,
            tz_output_default,
            status,
            priority,
            r#type,
            assignee,
            role,
        } => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            // Determine output destination
            if let Some(path) = output {
                // -o flag provided: write to specified file
                let count = storage.export_to_jsonl(
                    &path,
                    status,
                    priority,
                    r#type,
                    assignee.as_deref(),
                    role,
                )?;
                eprintln!("Exported {} issues to {}", count, path.display());
            } else if tz_output_default {
                // --tz-output-default: write to storage/issues.jsonl
                let path = storage.get_tazk_dir().join("issues.jsonl");
                let count = storage.export_to_jsonl(
                    &path,
                    status,
                    priority,
                    r#type,
                    assignee.as_deref(),
                    role,
                )?;
                eprintln!("Exported {} issues to {}", count, path.display());
            } else {
                // Default: write to stdout
                // Convert single priority to vector for list_issues
                let priority_list = priority.map(|p| vec![p]);
                let mut issues = storage.list_issues(
                    status,
                    priority_list,
                    r#type,
                    assignee.as_deref(),
                    None,
                )?;
                if let Some(role) = role {
                    issues.retain(|issue| issue.role == Some(role));
                }
                for issue in &issues {
                    let json = serde_json::to_string(&issue)?;
                    println!("{}", json);
                }
            }
            Ok(())
        }

        Commands::Sync {
            jsonl,
            dry_run,
            direction,
        } => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            let tazk_dir = storage.get_tazk_dir();
            let jsonl_path = jsonl.unwrap_or_else(|| tazk_dir.join("issues.jsonl"));

            // Load issues from both sources
            let markdown_issues = sync::load_markdown_issues(&tazk_dir)?;
            let jsonl_issues = sync::load_jsonl_issues(&jsonl_path)?;

            // Create sync engine and analyze
            let engine = sync::SyncEngine::new();
            let plan = engine.analyze_ref(&markdown_issues, &jsonl_issues)?;

            // Filter plan based on direction
            let filtered_plan = match direction.as_str() {
                "both" => plan,
                "to-jsonl" => sync::SyncPlan {
                    markdown_only: plan.markdown_only,
                    jsonl_only: Vec::new(),
                    markdown_newer: plan.markdown_newer,
                    jsonl_newer: Vec::new(),
                    no_change: plan.no_change,
                    conflicts: plan.conflicts,
                },
                "to-markdown" => sync::SyncPlan {
                    markdown_only: Vec::new(),
                    jsonl_only: plan.jsonl_only,
                    markdown_newer: Vec::new(),
                    jsonl_newer: plan.jsonl_newer,
                    no_change: plan.no_change,
                    conflicts: plan.conflicts,
                },
                _ => {
                    anyhow::bail!(
                        "Invalid direction '{}'. Use 'both', 'to-jsonl', or 'to-markdown'",
                        direction
                    );
                }
            };

            // Report plan
            if !json && !filtered_plan.is_empty() {
                println!("Sync plan:");
                if !filtered_plan.markdown_only.is_empty() {
                    println!("  Create in JSONL ({}):", filtered_plan.markdown_only.len());
                    for id in &filtered_plan.markdown_only {
                        println!("    {}", id);
                    }
                }
                if !filtered_plan.jsonl_only.is_empty() {
                    println!("  Create in markdown ({}):", filtered_plan.jsonl_only.len());
                    for id in &filtered_plan.jsonl_only {
                        println!("    {}", id);
                    }
                }
                if !filtered_plan.markdown_newer.is_empty() {
                    println!(
                        "  Update JSONL from markdown ({}):",
                        filtered_plan.markdown_newer.len()
                    );
                    for id in &filtered_plan.markdown_newer {
                        println!("    {}", id);
                    }
                }
                if !filtered_plan.jsonl_newer.is_empty() {
                    println!(
                        "  Update markdown from JSONL ({}):",
                        filtered_plan.jsonl_newer.len()
                    );
                    for id in &filtered_plan.jsonl_newer {
                        println!("    {}", id);
                    }
                }
                if !filtered_plan.conflicts.is_empty() {
                    println!("  Conflicts ({}):", filtered_plan.conflicts.len());
                    for id in &filtered_plan.conflicts {
                        println!("    {}", id);
                    }
                }
                println!();
            }

            // Apply sync
            let report = engine.apply_to_path(
                &filtered_plan,
                &markdown_issues,
                &jsonl_issues,
                &tazk_dir,
                &jsonl_path,
                dry_run,
            )?;

            // Report results
            if json {
                println!("{}", serde_json::to_string_pretty(&report)?);
            } else {
                if dry_run {
                    println!("[DRY RUN] Would make {} changes", report.total_changes());
                } else {
                    println!("Sync complete: {} changes applied", report.total_changes());
                }
                if report.created_in_jsonl > 0 {
                    println!("  Created in JSONL: {}", report.created_in_jsonl);
                }
                if report.created_in_markdown > 0 {
                    println!("  Created in markdown: {}", report.created_in_markdown);
                }
                if report.updated_jsonl > 0 {
                    println!("  Updated JSONL: {}", report.updated_jsonl);
                }
                if report.updated_markdown > 0 {
                    println!("  Updated markdown: {}", report.updated_markdown);
                }
                if report.skipped_conflicts > 0 {
                    println!("  Skipped conflicts: {}", report.skipped_conflicts);
                }
                if !report.errors.is_empty() {
                    println!("\nErrors:");
                    for error in &report.errors {
                        println!("  {}", error);
                    }
                }
            }
            anyhow::ensure!(
                report.errors.is_empty(),
                "Sync completed with {} unresolved errors",
                report.errors.len()
            );
            Ok(())
        }

        Commands::Ready {
            assignee,
            role,
            priority,
            r#type,
            labels,
            id,
            title,
            parent,
            limit,
            group_priority,
            sort,
        } => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            // Validate sort policy
            let sort_policy = match sort.as_str() {
                "priority" | "oldest" | "hybrid" | "random" => sort.as_str(),
                _ => {
                    eprintln!("Warning: Invalid sort policy '{}', using 'hybrid'", sort);
                    "hybrid"
                }
            };

            let priority_list = parse_priority_filters(&priority)?;

            let mut ready =
                storage.get_ready(assignee.as_deref(), priority_list, r#type, sort_policy)?;

            // Apply in-memory filters shared with `list`
            IssueFilters {
                labels: &labels,
                id: id.as_deref(),
                title: title.as_deref(),
                parent: parent.as_deref(),
                role,
            }
            .apply(&mut ready);

            // Shuffle after filtering so `-n 1 -s random` picks uniformly from
            // the whole filtered set, not just its head.
            if sort_policy == "random" {
                use rand::seq::SliceRandom;
                ready.shuffle(&mut rand::thread_rng());
            }

            // Apply limit after every filter has run
            if let Some(limit_val) = limit {
                if limit_val > 0 {
                    ready.truncate(limit_val);
                }
            }

            if json {
                println!("{}", serde_json::to_string_pretty(&ready)?);
            } else if group_priority {
                print_issues_grouped_by_priority(&ready);
            } else {
                for issue in ready {
                    println!(
                        "{}: {} [priority: {}]",
                        issue.id, issue.title, issue.priority
                    );
                }
            }
            Ok(())
        }

        Commands::Quickstart => {
            print_quickstart();
            Ok(())
        }

        Commands::Version => {
            println!("tz version {}", env!("CARGO_PKG_VERSION"));
            Ok(())
        }

        Commands::MergeDriver { command } => run_merge_driver_command(command),

        Commands::Migrate {
            to,
            dry_run,
            tz_patch_code,
            no_change_config,
            repack_contiguous,
            closed_issue_start,
        } => {
            let storage = get_storage(tz_dir, readonly)?;

            // Log command after storage is validated
            if !tz_no_cmd_logging {
                let _ = log_command(&storage.get_tazk_dir(), &env::args().collect::<Vec<_>>());
            }

            // Validate that --closed-issue-start is only valid with --repack-contiguous
            if closed_issue_start.is_some() && !repack_contiguous {
                anyhow::bail!("--closed-issue-start is only valid with --repack-contiguous");
            }

            // Handle --repack-contiguous separately (fills gaps in numeric IDs)
            if repack_contiguous {
                let (changes, id_mapping) =
                    storage.repack_numeric_ids(dry_run, closed_issue_start)?;

                if json {
                    println!("{}", serde_json::to_string_pretty(&changes)?);
                } else if dry_run {
                    println!("Dry run - would make the following changes:");
                    for change in &changes {
                        println!("  {}", change);
                    }
                } else {
                    let issue_count = changes
                        .iter()
                        .filter(|c| c.starts_with("Rename file:"))
                        .count();
                    if issue_count > 0 {
                        println!(
                            "Successfully repacked {} issue(s) to fill gaps",
                            issue_count
                        );

                        // Patch code references if requested
                        if tz_patch_code {
                            if let Err(e) = code_patch::patch_code_for_migration(&id_mapping) {
                                eprintln!("Warning: Code patching failed: {}", e);
                            }
                        }
                    } else {
                        // No changes made
                        for change in &changes {
                            println!("{}", change);
                        }
                    }
                }
                return Ok(());
            }

            match to.as_str() {
                "hash" => {
                    let update_config = !no_change_config;
                    let (changes, id_mapping) =
                        storage.migrate_to_hash_ids(dry_run, update_config)?;

                    if json {
                        println!("{}", serde_json::to_string_pretty(&changes)?);
                    } else if dry_run {
                        println!("Dry run - would make the following changes:");
                        for change in &changes {
                            println!("  {}", change);
                        }
                    } else {
                        println!(
                            "Successfully migrated {} issue(s) to hash-based IDs",
                            changes.len() / 3
                        );
                        if update_config {
                            println!("Updated config-tazk.yaml: tz-hash-ids: true");
                        }

                        // Patch code references if requested
                        if tz_patch_code {
                            if let Err(e) = code_patch::patch_code_for_migration(&id_mapping) {
                                eprintln!("Warning: Code patching failed: {}", e);
                            }
                        }
                    }
                }
                "numeric" => {
                    let update_config = !no_change_config;
                    let (changes, id_mapping) =
                        storage.migrate_to_numeric_ids(dry_run, update_config)?;

                    if json {
                        println!("{}", serde_json::to_string_pretty(&changes)?);
                    } else if dry_run {
                        println!("Dry run - would make the following changes:");
                        for change in &changes {
                            println!("  {}", change);
                        }
                    } else {
                        let issue_count = changes
                            .iter()
                            .filter(|c| c.starts_with("Rename file:"))
                            .count();
                        println!(
                            "Successfully migrated {} issue(s) to numeric IDs",
                            issue_count
                        );
                        if update_config {
                            println!("Updated config-tazk.yaml: tz-hash-ids: false");
                        }

                        // Patch code references if requested
                        if tz_patch_code {
                            if let Err(e) = code_patch::patch_code_for_migration(&id_mapping) {
                                eprintln!("Warning: Code patching failed: {}", e);
                            }
                        }
                    }
                }
                "sharded" | "flat" => {
                    let update_config = !no_change_config;
                    let target_layout = if to == "sharded" {
                        IssueStorageLayout::Sharded
                    } else {
                        IssueStorageLayout::Flat
                    };
                    let changes = storage.migrate_issue_storage_layout(
                        target_layout,
                        dry_run,
                        update_config,
                    )?;

                    if json {
                        println!("{}", serde_json::to_string_pretty(&changes)?);
                    } else if dry_run {
                        println!("Dry run - would make the following changes:");
                        for change in &changes {
                            println!("  {}", change);
                        }
                    } else {
                        let issue_count = changes
                            .iter()
                            .filter(|c| c.starts_with("Move issue "))
                            .count();
                        if issue_count > 0 {
                            println!(
                                "Successfully migrated {} issue file(s) to {} layout",
                                issue_count,
                                target_layout.as_str()
                            );
                        } else {
                            for change in &changes {
                                println!("{}", change);
                            }
                        }
                        if update_config {
                            println!(
                                "Updated config-tazk.yaml: issue-storage-layout: {}",
                                target_layout.as_str()
                            );
                        }
                    }
                }
                _ => {
                    anyhow::bail!(
                        "Invalid migration target '{}'. Use '--to=hash', '--to=numeric', '--to=sharded', or '--to=flat'",
                        to
                    );
                }
            }
            Ok(())
        }
    }
}

fn get_storage(tz_dir: &Option<PathBuf>, readonly: bool) -> Result<Storage> {
    // Priority order for determining the database directory:
    // 1. --tz-dir flag
    // 2. TAZK_DIR environment variable
    // 3. Search for .tazk in the current directory and ancestors

    let tazk_dir = if let Some(dir) = tz_dir {
        dir.clone()
    } else if let Ok(tazk_dir) = env::var("TAZK_DIR") {
        PathBuf::from(tazk_dir)
    } else {
        find_tazk_dir()?
    };

    if readonly {
        Storage::open_readonly(tazk_dir)
    } else {
        Storage::open(tazk_dir)
    }
    .context("Failed to open storage")
}

fn find_tazk_dir() -> Result<PathBuf> {
    let start = env::current_dir()?;
    if let Some(dir) = find_storage_dir_named(&start, PRIMARY_STORAGE_DIR)? {
        return Ok(dir);
    }

    anyhow::bail!(
        "No {} directory found. Run 'tz init' to initialize a new database.",
        PRIMARY_STORAGE_DIR
    );
}

fn find_storage_dir_named(start: &Path, dir_name: &str) -> Result<Option<PathBuf>> {
    let mut current = start.to_path_buf();
    loop {
        let candidate = current.join(dir_name);
        if candidate.exists() && candidate.is_dir() {
            return Ok(Some(candidate));
        }

        if !current.pop() {
            return Ok(None);
        }
    }
}

/// Log command to command_history.log
fn log_command(tazk_dir: &Path, args: &[String]) -> Result<()> {
    use std::fs::OpenOptions;
    use std::io::Write;

    let log_path = tazk_dir.join("command_history.log");
    let timestamp = chrono::Utc::now().to_rfc3339();

    // Debug quoting keeps embedded newlines from forging another history entry.
    // Skip the first argument (binary path) and quote each CLI argument
    let command_line = if args.len() > 1 {
        args[1..]
            .iter()
            .map(|arg| format!("{arg:?}"))
            .collect::<Vec<_>>()
            .join(" ")
    } else {
        String::new()
    };

    let mut file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(&log_path)
        .context("Failed to open command history log")?;

    writeln!(file, "<<BD_INVOKE>> {} {}", timestamp, command_line)
        .context("Failed to write to command history log")?;

    Ok(())
}

/// Print a human-readable summary of a successful claim.
fn print_claim_result(issue: &types::Issue) {
    println!("Claimed {} as '{}'", issue.id, issue.assignee);
}

fn print_quickstart() {
    println!(
        r#"tz - Dependency-Aware Issue Tracker

Issues chained together by dependencies.

GETTING STARTED
  tz init   Initialize tz in your project
            Creates .tazk/ directory with project-specific database
            Auto-detects prefix from directory name (e.g., myapp-1, myapp-2)

  tz init --prefix api   Initialize with custom prefix
            Issues will be named: api-1, api-2, ...

CREATING ISSUES
  tz create "Fix login bug" -r agent   --role (human|agent) is required
  tz create "Add auth" -r human -p 0 -t feature
  tz create "Write tests" -r agent -d "Unit tests for auth" --assignee alice
  tz create "Triage logs" -r agent --effort 2   Effort: 1-5

REPORTING AND TRIAGING
  Triage items are plain-text reports in .tazk/triage/, not issues: no title,
  status, priority, role or assignee. Report freely; plan later.
  tz triage add "Login fails on Safari"   Report something found in review/testing
  git log -1 --format=%H | tz triage add "Regression after this commit"
            Piped stdin is appended (external refs, logs, review output)
  tz triage list                          Item file names, e.g. 20251104T001800-k3f9.md
  tz triage show 20251104T001800-k3f9     Print an item (.md optional)
  tz triage update NAME --search old --replace new   (or --append TEXT)
  tz triage promote NAME... --title "Fix Safari login" -r agent -p 1
            Triager: one issue from one or more items (items are deleted)
  tz triage attach NAME... --to myapp-3 --author NAME   Add items as comments on an issue
  tz triage rm NAME...                    Discard items

VIEWING ISSUES
  tz list       List all issues
  tz list --status open  List by status
  tz list --priority 0  List by priority (0-4, 0=highest)
  tz list --role agent  List by role (human, agent)
  tz ready --role agent Ready work for a role
  tz show myapp-1       Show issue details

MANAGING DEPENDENCIES
  tz dep add myapp-1 --target myapp-2     Add dependency (myapp-1 is blocked_by myapp-2)

DEPENDENCY TYPES
  blocked_by  This task can't start until the target task is complete
  related_to  Soft connection, doesn't block progress
  child_of  This task is a subtask of the target (epic)
  discovered_from  Auto-created when AI discovers related work
  tracks  Tracks the target task

READY WORK
  tz ready       Show issues ready to work on
            Ready = status is 'open' AND no blocking dependencies
            Perfect for agents to claim next work!

CLAIMING WORK (cross-machine coordination)
  tz claim myapp-1 --as alice   Claim an issue as 'alice' (--as is required)
            Sets assignee to the --as value, status to in_progress, and bumps
            updated_at. Fails if the issue is already in_progress or closed.
  tz claim myapp-1 --as alice --team backend   Identity becomes 'alice/backend'
  tz claim myapp-1 --as alice --force   Take an issue that is already in_progress
  tz claim myapp-1 --as alice --release   Release the claim (back to 'open')
  tz claim myapp-1 --as bob --release --force   Release another worker's claim

            HOW THE LOCK WORKS: a claim is just a small commit. Claim the issue,
            commit, and push to the shared branch. If two machines race, the
            losing 'git push' is rejected; that worker pulls, sees the issue is
            in_progress, and moves on. Typical agent flow when starting work on
            an already-committed backlog issue:
              tz claim myapp-1 --as alice && git commit -am "claim myapp-1" && git push

UPDATING ISSUES
  tz update myapp-1 --priority 0
  tz update myapp-1 --assignee bob

EDITING DESCRIPTIONS (do NOT hand-edit the .tazk/*.md files!)
  Always go through 'tz' to change an issue. To revise long text, use a
  targeted search/replace edit instead of overwriting the whole field with
  --description (which is error-prone and drops content):

  tz update myapp-1 --search "old wording" --replace "new wording"
  tz update myapp-1 --field design --search "foo" --replace "bar"
  tz update myapp-1 --search "TODO" --replace "DONE" --replace-all

            The --search text must match the field EXACTLY (including newlines)
            and, by default, match exactly once -- include enough surrounding
            context to be unambiguous. A missing or ambiguous match is an error
            and the issue is left untouched, so the edit is safe to retry.
            --field selects the text field (title, description, design, notes,
            acceptance; default description).

  To simply add to the end of a field, use --append instead of reproducing
  the trailing text as a search/replace:

  tz update myapp-1 --append "A new closing paragraph."
  tz update myapp-1 --field design --append "An extra design note."

            --append inserts a blank line before the new text when the field is
            non-empty, so it lands as its own paragraph.

CLOSING ISSUES
  tz close myapp-1
  tz close myapp-1 --reason "Fixed in PR #42"

DATABASE LOCATION
  tz automatically discovers your database in this priority order:
    1. --tz-dir /path/to/.tazk
    2. $TAZK_DIR environment variable
    3. .tazk/ in current directory or ancestors

Ready to start!
Run tz create "My first issue" -r agent to create your first issue.
"#
    );
}

#[cfg(test)]
mod body_input_tests {
    use super::*;
    use std::io::Write;

    /// Inline stays inline when no file is given.
    #[test]
    fn inline_body_passes_through() {
        let got = resolve_body(Some("inline".to_string()), None).unwrap();
        assert_eq!(got.as_deref(), Some("inline"));
    }

    /// A file body is read verbatim -- INCLUDING backticks and $(...), which is
    /// the entire point: nothing between the file and the store can expand them.
    #[test]
    fn file_body_preserves_shell_metacharacters() {
        let mut f = tempfile::NamedTempFile::new().unwrap();
        let raw = "so both `echo SWALLOWED` and a bare $(echo GONE) survive";
        write!(f, "{raw}").unwrap();
        let got = resolve_body(None, Some(f.path().display().to_string()))
            .unwrap()
            .unwrap();
        assert_eq!(got, raw, "file body must be byte-identical");
        assert!(got.contains('`'), "backticks must survive: {got}");
        assert!(got.contains("$("), "dollar-parens must survive: {got}");
    }

    /// A missing file is a loud error, never an empty body. An empty body would
    /// be a successful write of wrong content -- the exact failure mode this
    /// whole feature exists to remove.
    #[test]
    fn missing_file_errors_rather_than_storing_empty() {
        let err = resolve_body(None, Some("/nonexistent/body.md".to_string()));
        assert!(
            err.is_err(),
            "missing file must error, not yield an empty body"
        );
    }

    /// The file wins when both are somehow present. Clap rejects the
    /// combination at parse time, so this pins the library-level behaviour too.
    #[test]
    fn file_takes_precedence_over_inline() {
        let mut f = tempfile::NamedTempFile::new().unwrap();
        write!(f, "from file").unwrap();
        let got = resolve_body(
            Some("from inline".to_string()),
            Some(f.path().display().to_string()),
        )
        .unwrap()
        .unwrap();
        assert_eq!(got, "from file");
    }
}
